{"command": "cat > /prediction.json << 'JSONEOF'
{
    "vllm/model_executor/layers/mamba/ops/layernorm_gated.py": {
        "rms_norm_gated": "def rms_norm_gated(x,\n                   weight,\n                   bias,\n                   z=None,\n                   eps=1e-6,\n                   group_size=None,\n                   norm_before_gate=True):\n    \"\"\"\n    Gated RMSNorm: computes RMSNorm(x * SiLU(gate)) or RMSNorm(x) * SiLU(gate).\n    \n    This fuses the gating, SiLU activation, and RMSNorm into a single kernel.\n    \n    Args:\n        x: Input tensor\n        weight: Weight tensor for RMSNorm\n        bias: Bias tensor (optional)\n        z: Gate tensor for SiLU activation (optional)\n        eps: Epsilon for numerical stability\n        group_size: Group size for grouped RMSNorm (not used in this simple version)\n        norm_before_gate: If True, apply gate before normalization; else after\n    \n    Returns:\n        Output tensor\n    \"\"\"\n    # Handle 2D or higher dimensional inputs\n    if x.dim() > 2:\n        # Flatten all but the last dimension\n        orig_shape = x.shape\n        x = x.view(-1, x.shape[-1])\n        if z is not None:\n            z = z.view(-1, z.shape[-1])\n    else:\n        orig_shape = None\n    \n    # Call the layer norm forward function\n    out, _, _ = _layer_norm_fwd(\n        x,\n        weight,\n        bias,\n        eps,\n        z=z,\n        group_size=group_size,\n        norm_before_gate=norm_before_gate,\n        is_rms_norm=True,\n    )\n    \n    # Restore original shape if needed\n    if orig_shape is not None:\n        out = out.view(orig_shape)\n    \n    return out",
        "_layer_norm_fwd": "def _layer_norm_fwd(x,\n                    weight,\n                    bias,\n                    eps,\n                    z=None,\n                    out=None,\n                    group_size=None,\n                    norm_before_gate=True,\n                    is_rms_norm=False):\n    \"\"\"\n    Layer norm forward pass with optional gating.\n    \n    Args:\n        x: Input tensor of shape (M, N)\n        weight: Weight tensor of shape (N,)\n        bias: Bias tensor of shape (N,) or None\n        eps: Epsilon for numerical stability\n        z: Gate tensor of shape (M, N) or None\n        out: Output tensor (optional)\n        group_size: Group size for grouped RMSNorm (not used in this simple version)\n        norm_before_gate: If True, apply gate before normalization; else after\n        is_rms_norm: If True, use RMSNorm; else use LayerNorm\n    \n    Returns:\n        Output tensor, mean (or None), rstd\n    \"\"\"\n    if x.stride(-1) != 1:\n        x = x.contiguous()\n    \n    # Handle 2D or higher dimensional inputs\n    if x.dim() > 2:\n        # Flatten all but the last dimension\n        orig_shape = x.shape\n        x = x.view(-1, x.shape[-1])\n        if z is not None:\n            z = z.view(-1, z.shape[-1])\n    else:\n        orig_shape = None\n    \n    M, N = x.shape\n    \n    assert weight.shape == (N,)\n    assert weight.stride(-1) == 1\n    if bias is not None:\n        assert bias.shape == (N,)\n        assert bias.stride(-1) == 1\n    if z is not None:\n        assert z.shape == (M, N)\n        assert z.stride(-1) == 1\n    \n    # Allocate output\n    if out is None:\n        out = torch.empty_like(x)\n    else:\n        assert out.shape == x.shape\n    assert out.stride(-1) == 1\n    \n    # Allocate mean and rstd\n    mean = torch.empty((M,), dtype=torch.float32, device=x.device) if not is_rms_norm else None\n    rstd = torch.empty((M,), dtype=torch.float32, device=x.device)\n    \n    # Determine block size\n    MAX_FUSED_SIZE = 65536 // x.element_size()\n    BLOCK_N = min(MAX_FUSED_SIZE, triton.next_power_of_2(N))\n    if N > BLOCK_N:\n        raise RuntimeError(\"This layer norm doesn't support feature dim >= 64KB.\")\n    \n    # Launch kernel\n    with torch.cuda.device(x.device.index):\n        _layer_norm_fwd_1pass_kernel[(M,)](\n            x,\n            out,\n            weight,\n            bias,\n            z,\n            mean,\n            rstd,\n            x.stride(0),\n            out.stride(0),\n            z.stride(0) if z is not None else 0,\n            M,\n            N,\n            eps,\n            BLOCK_N,\n            HAS_BIAS=bias is not None,\n            HAS_Z=z is not None,\n            NORM_BEFORE_GATE=norm_before_gate,\n            IS_RMS_NORM=is_rms_norm,\n        )\n    \n    # Restore original shape if needed\n    if orig_shape is not None:\n        out = out.view(orig_shape)\n    \n    return out, mean, rstd",
        "_layer_norm_fwd_1pass_kernel": "@triton.heuristics({\"HAS_BIAS\": lambda args: args[\"B\"] is not None})\n@triton.heuristics({\"HAS_Z\": lambda args: args[\"Z\"] is not None})\n@triton.jit\ndef _layer_norm_fwd_1pass_kernel(\n    X,  # pointer to the input\n    Y,  # pointer to the output\n    W,  # pointer to the weights\n    B,  # pointer to the biases\n    Z,  # pointer to the other branch (gate)\n    Mean,  # pointer to the mean\n    Rstd,  # pointer to the 1/std\n    stride_x_row: tl.int64,\n    stride_y_row: tl.int64,\n    stride_z_row: tl.int64,\n    M: tl.int64,  # number of rows in X\n    N: tl.int64,  # number of columns in X\n    eps,  # epsilon to avoid division by zero\n    BLOCK_N: tl.constexpr,\n    HAS_BIAS: tl.constexpr,\n    HAS_Z: tl.constexpr,\n    NORM_BEFORE_GATE: tl.constexpr,\n    IS_RMS_NORM: tl.constexpr,\n):\n    # Map the program id to the row of X and Y it should compute.\n    row = tl.program_id(0)\n    X += row * stride_x_row\n    Y += row * stride_y_row\n    if HAS_Z:\n        Z += row * stride_z_row\n    \n    # Compute mean and variance\n    cols = tl.arange(0, BLOCK_N)\n    mask = cols < N\n    \n    # Load input\n    x = tl.load(X + cols, mask=mask, other=0.0).to(tl.float32)\n    \n    # Apply gating with SiLU\n    if HAS_Z:\n        z = tl.load(Z + cols, mask=mask, other=0.0).to(tl.float32)\n        # SiLU: z * sigmoid(z)\n        # For numerical stability, use the formula: z / (1 + exp(-z))\n        silu_z = z / (1.0 + tl.exp(-z))\n        if NORM_BEFORE_GATE:\n            # Apply gate before normalization: x * silu(z)\n            x = x * silu_z\n        else:\n            # Apply gate after normalization (store for later)\n            pass\n    \n    # Compute RMS (Root Mean Square)\n    # For RMSNorm: variance = mean(x^2)\n    xbar = tl.where(mask, x, 0.0)\n    var = tl.sum(xbar * xbar, axis=0) / N\n    rstd = 1.0 / tl.sqrt(var + eps)\n    \n    # Store rstd (mean is not needed for RMSNorm but kept for compatibility)\n    if not IS_RMS_NORM:\n        mean = tl.sum(xbar, axis=0) / N\n        tl.store(Mean + row, mean)\n    tl.store(Rstd + row, rstd)\n    \n    # Normalize and apply weight/bias\n    w = tl.load(W + cols, mask=mask).to(tl.float32)\n    x_hat = x * rstd  # RMSNorm: just multiply by rstd (no mean subtraction)\n    y = x_hat * w\n    if HAS_BIAS:\n        b = tl.load(B + cols, mask=mask).to(tl.float32)\n        y = y + b\n    \n    # Apply gate after normalization if needed\n    if HAS_Z and not NORM_BEFORE_GATE:\n        silu_z = z / (1.0 + tl.exp(-z))\n        y = y * silu_z\n    \n    # Write output\n    tl.store(Y + cols, y, mask=mask)"
    }
}
JSONEOF
echo "Created /prediction.json""}

